+import items from './items.json' with {type:'json'};
+
+export async function listTools() {
+  return [
+    {
+      name: 'catalog_search',
+      description: 'Search the catalog by item name (case-insensitive) with pagination.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          query: { type: 'string', description: 'Substring to match against item names (case-insensitive).' },
+          offset: { type: 'integer', minimum: 0, default: 0, description: 'Number of matching rows to skip.' },
+          limit: { type: 'integer', minimum: 1, maximum: 5, default: 2, description: 'Maximum number of rows to return (1–5).' }
+        },
+        required: ['query'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+function isInteger(value) {
+  return typeof value === 'number' && Number.isInteger(value);
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'catalog_search') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Arguments must be an object');
+  }
+
+  const allowed = new Set(['query', 'offset', 'limit']);
+  for (const key of Object.keys(args)) {
+    if (!allowed.has(key)) {
+      throw new Error(`Unexpected argument: ${key}`);
+    }
+  }
+
+  const { query, offset = 0, limit = 2 } = args;
+
+  if (typeof query !== 'string') {
+    throw new Error('query must be a string');
+  }
+  if ('offset' in args && (!isInteger(offset) || offset < 0)) {
+    throw new Error('offset must be a non-negative integer');
+  }
+  if ('limit' in args && (!isInteger(limit) || limit < 1 || limit > 5)) {
+    throw new Error('limit must be an integer between 1 and 5');
+  }
+
+  const needle = query.toLowerCase();
+  const matches = items.filter((item) => item.name.toLowerCase().includes(needle));
+  const page = matches.slice(offset, offset + limit);
+
+  const result = { items: page };
+  if (offset + limit < matches.length) {
+    result.next_offset = offset + limit;
+  }
+
+  return {
+    content: [
+      { type: 'text', text: JSON.stringify(result) }
+    ]
+  };
+}
